use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\AutomaticJudgeBrowserService;use App\Services\ScoringRosterCheckpointService;
Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_POST['round_id']??0);$return='automatic-round.php?round_id='.$roundId;
try{
 if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid request. Refresh the dashboard and try again.');
