  $bdc='';if(preg_match('/^(BDC-\d+)/i',$term,$m))$bdc=strtoupper($m[1]);$q=$pdo->prepare("SELECT id,bdc_id,exact_name,dance_role FROM bdc_competitors WHERE status<>'archived' AND dance_role=:role AND (bdc_id=:bdc OR LOWER(exact_name)=LOWER(:name)) ORDER BY CASE WHEN bdc_id=:preferred THEN 0 ELSE 1 END,id LIMIT 2");$q->execute(['role'=>$role,'bdc'=>$bdc!==''?$bdc:$term,'name'=>$term,'preferred'=>$bdc]);$matches=$q->fetchAll();if(count($matches)>1&&$bdc==='')throw new RuntimeException('Several '.$role.' competitors have this name. Select the exact BDC ID.');$competitor=$matches[0]??null;
