 }elseif($action==='remove_entry'){ScoringRosterCheckpointService::assertEditable($pdo,$roundId);$entryId=(int)($_POST['entry_id']??0);$pdo->prepare("UPDATE bdc_scoring_entries SET entry_status='withdrawn' WHERE id=:entry AND round_id=:round")->execute(['entry'=>$entryId,'round'=>$roundId]);$message='Competitor removed from this round.';
