 }elseif($action==='reopen_competitors'){if(!Auth::isSuperAdmin())throw new RuntimeException('Only the Super Admin can reopen submitted competitors.');ScoringRosterCheckpointService::checkpoint($pdo,$roundId,$userId,'reopen',false,(string)($_POST['reopen_reason']??''));$message='Competitor roster reopened for correction.';
